template <typename UnionPtrType>
MediaStoreMetadataPtr MediaStoreMetadata::Clone() const {
  switch (tag_) {
    case Tag::kUnknown:
      return NewUnknown(
          mojo::Clone(data_.unknown));
    case Tag::kDownload:
      return NewDownload(
          mojo::Clone(*data_.download));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, MediaStoreMetadata>::value>::type*>
bool MediaStoreMetadata::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kUnknown:
      return mojo::Equals(data_.unknown, other.data_.unknown);
    case Tag::kDownload:
      return mojo::Equals(*(data_.download), *(other.data_.download));
  }

  return false;
}
